INSERT INTO `chat_questions` (`id`, `question`, `answer`, `domain`, `sort`, `is_main`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Есть ли товар в наличии?', '{\"time\":1692388522610,\"blocks\":[{\"id\":\"oxDb8dq9L8\",\"type\":\"paragraph\",\"data\":{\"text\":\"Мы работаем круглый год, а значит, у нас всегда есть, необходимый для работы, запас продукции на наших складах. В случае, если интересующий Вас товар, отсутствует в наличии, свяжитесь с нами для решения вопроса.\"}}],\"version\":\"2.25.0\"}', 'kulikofta.ru', 2, 1, '2022-09-21 19:09:31', '2023-08-18 19:55:21', NULL),
(2, 'Какой состав у свитеров?', '{\"time\":1692388712449,\"blocks\":[{\"id\":\"wfW53x8fIX\",\"type\":\"paragraph\",\"data\":{\"text\":\"Наши свитеры не колятся и приятны к телу. Данный эффект достигается идеальным соотношением материалов, выверенный годами.\"}},{\"id\":\"YyhHoZDuYb\",\"type\":\"paragraph\",\"data\":{\"text\":\" <br>Большая часть нашей продукции имеет следующий состав:<br><i><b>Шерсть</b>: 30%; <b>Хлопок</b>: 20%; <b>ПАН</b>: 50%.</i>\"}}],\"version\":\"2.25.0\"}', 'kulikofta.ru', 3, 1, '2022-09-21 20:19:06', '2023-08-18 19:58:30', NULL),
(3, 'Как производится оплата?', '{\"time\":1686424206437,\"blocks\":[{\"id\":\"aeVHtKkcbt\",\"type\":\"paragraph\",\"data\":{\"text\":\"Мы заключаем договор с каждым клиентом (физ. лица, юр. лица). Оплату принимаем, как наличными, так и по безналу (оплата по выставленному счету).\"}}],\"version\":\"2.25.0\"}', 'kulikofta.ru', 4, 1, '2022-09-23 05:22:26', '2023-06-10 19:10:08', NULL),
(4, 'Как сделать оптовый заказ?', '{\"time\":1695133227517,\"blocks\":[{\"id\":\"NE9Q814ddJ\",\"type\":\"paragraph\",\"data\":{\"text\":\"Вы можете оформить заказ на нашем сайте, либо связаться с нашим менеджером по телефону:<br><b>+7 (995) 466-40-44.</b> \"}},{\"id\":\"iDNplqwA9Y\",\"type\":\"paragraph\",\"data\":{\"text\":\"<i>Напишите Ваше сообщение в этот чат, нажмите \\\"Отправить\\\" и Вас перенаправит в переписку с нашим менеджером в WhatsApp.</i>\"}}],\"version\":\"2.25.0\"}', 'kulikofta.ru', 1, 1, '2022-09-23 05:31:28', '2023-09-19 14:20:28', NULL);
